-- pipeline/fail-stale-runs
-- When the worker starts, a run still marked running from a crashed worker is closed as failed.
--
-- Parameters, with the example values used to render this file:
--   $1 = "failed"
--   $2 = "worker stopped during the run"
--   $3 = "running"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

update "pipeline_runs"
set "status" = $1, "finished_at" = now(), "error" = $2, "updated_at" = now()
where "pipeline_runs"."status" = $3
returning "id";
